param([switch]$CheckOnly,[string]$Namespace='resilient-microservices-adaptive-recovery',[string]$ChaosName='adaptive-product-e6-pod-kill')
$ErrorActionPreference='Stop'
$root=Split-Path $PSScriptRoot -Parent;$reports=Join-Path $root 'reports';New-Item -ItemType Directory -Force $reports|Out-Null
$kubectl=if($env:KUBECTL_BIN){$env:KUBECTL_BIN}else{(Get-Command kubectl -ErrorAction Stop).Source};if(-not(Test-Path $kubectl)){ throw "kubectl executable not found: $kubectl" }
$manifest=Join-Path $root 'infrastructure/chaos/e6-product-pod-kill.yaml';$engine='http://127.0.0.1:8090';$product='http://127.0.0.1:18081';$now=[DateTimeOffset]::Now.ToOffset([TimeSpan]::FromHours(5.5));$runId='E6-'+$now.ToString('yyyyMMdd-HHmmssK').Replace(':','');$path=Join-Path $reports ('e6-product-pod-kill-'+$now.ToString('yyyyMMdd-HHmmssK').Replace(':','')+'.json');$progress=Join-Path $reports 'e6-progress.json';$created=$false;$uid=$null;$baselineUid=$null
$run=[ordered]@{experiment='E6';runId=$runId;runStatus='Running';result=$null;experimentOutcome=$null;definition='PodChaos pod-kill; Kubernetes ReplicaSet replaces Product pod';timezone='Asia/Kolkata (+05:30)';timestamps=[ordered]@{T0=$null;T1=$null;T2=$null;T3=$null;T4=$null;T5=$null;recoveryTime=$null;faultToRecoveryTime=$null;cleanupCompletionTime=$null};timestampDefinitions=[ordered]@{T0='Chaos Mesh confirms PodChaos injection';T1='Product interruption observed';T2='Replacement Product pod with a different UID detected';T3='Post-replacement non-mutating Recovery Engine observation with UID/readiness evidence';T4='Replacement Product pod Ready and Product health UP confirmed';T5='Chaos absence and final Product Ready/health independently verified'};timestampEvidence=[ordered]@{};baseline=[ordered]@{pod=$null;uid=$null;ready=$null;health=$null};replacement=[ordered]@{pod=$null;uid=$null;ready=$null;health=$null};forward=[ordered]@{startedByRunner=$false;pid=$null;error=$null};chaos=[ordered]@{name=$ChaosName;uid=$null;created=$false;injected=$false;injectionCondition=$null;deleted=$false;absenceVerified=$false};engineEvaluations=@();engineObservation=[ordered]@{decision=$null;reason=$null;verified=$false;uid=$null;ready=$null};measurements=@();cleanup=[ordered]@{attempted=$false;status=$null;error=$null};readiness=[ordered]@{before=$null;interrupted=$null;after=$null}}
$run['telemetry']=[ordered]@{resetScraped=$false;interruptionPublished=$null;healthyReplacementPublished=$null;eventsScraped=$null;error=$null}
Import-Module (Join-Path $PSScriptRoot 'e6-events.psm1') -Force
function IstNow{[DateTimeOffset]::Now.ToOffset([TimeSpan]::FromHours(5.5)).ToString('yyyy-MM-ddTHH:mm:ss.fffzzz')}
function Save-Run{$j=$run|ConvertTo-Json -Depth 20;$j|Set-Content -Encoding UTF8 $path;$j|Set-Content -Encoding UTF8 $progress}
function KJson([string[]]$a){$t=& $kubectl @a 2>$null|Out-String;if($LASTEXITCODE-ne 0){throw "kubectl failed: $($a -join ' ')"};$t|ConvertFrom-Json}
function K([string[]]$a){& $kubectl @a;if($LASTEXITCODE-ne 0){throw "kubectl failed: $($a -join ' ')"}}
function Product-Snapshot{$j=KJson @('-n',$Namespace,'get','pods','-l','app.kubernetes.io/name=adaptive-product-service','-o','json');$p=@($j.items|Sort-Object {$_.metadata.creationTimestamp}|Select-Object -Last 1);if(-not$p){return $null};$ready=(@($p.status.conditions|Where-Object {$_.type -eq 'Ready' -and $_.status -eq 'True'}).Count -gt 0);[ordered]@{name=$p.metadata.name;uid=$p.metadata.uid;ready=$ready}}
function Product-Health{try{$h=Invoke-RestMethod ($product+'/actuator/health') -TimeoutSec 5;return $h.status -eq 'UP'}catch{return $false}}
function Ensure-ProductForward{if(Product-Health){return $true};$existing=$null;try{$existing=Get-CimInstance Win32_Process|Where-Object{$_.CommandLine-and$_.CommandLine-match 'kubectl(\.exe)?'-and$_.CommandLine-like '*port-forward svc/adaptive-product-service 18081:8081*'}|Select-Object -First 1}catch{};if(-not$existing){$pf=Start-Process $kubectl -ArgumentList '-n',$Namespace,'port-forward','svc/adaptive-product-service','18081:8081' -PassThru -WindowStyle Hidden;$run.forward.startedByRunner=$true;$run.forward.pid=$pf.Id;try{$pf.Id|Add-Content (Join-Path $root 'gui\.portforward-pids')}catch{}};for($i=0;$i-lt 20;$i++){Start-Sleep -Milliseconds 500;if(Product-Health){return $true}};return $false}
function Chaos-Status{try{$c=KJson @('-n',$Namespace,'get','podchaos',$ChaosName,'-o','json');$in=@($c.status.conditions|Where-Object {$_.type -in @('AllInjected','Injected') -and $_.status -eq 'True'}).Count -gt 0;[ordered]@{uid=$c.metadata.uid;injected=$in;condition=if($in){'AllInjected=True/Injected=True'}else{'Not injected'}}}catch{return $null}}
function Chaos-Absent{$text=& $kubectl '-n' $Namespace 'get' 'podchaos' $ChaosName '--ignore-not-found' '-o' 'json' 2>$null;if($LASTEXITCODE-ne 0){return $false};return [string]::IsNullOrWhiteSpace(($text|Out-String))}
function Wait-Injected{for($i=0;$i-lt 20;$i++){$s=Chaos-Status;if($s){$run.chaos.injectionCondition=$s.condition;$run.chaos.injected=$s.injected;if($s.injected){return $true}};Start-Sleep 1};return $false}
function Other-Experiment-Running{$expected=@{'e1-gui-run-state.json'='run-e1-inventory-cpu.ps1';'e2-gui-run-state.json'='run-e2-inventory-memory.ps1';'e3-gui-run-state.json'='run-e3-order-inventory-delay.ps1';'e4-gui-run-state.json'='run-e4-order-http500.ps1'};foreach($f in $expected.Keys){$s=Join-Path $reports $f;if(Test-Path $s){$x=Get-Content $s -Raw|ConvertFrom-Json;if($x.pid){try{$p=Get-CimInstance Win32_Process -Filter "ProcessId = $([int]$x.pid)";if($p.CommandLine -and $p.CommandLine -like "*$($expected[$f])*"){return $true}}catch{}}}};return $false}
function Evaluate([string]$phase='interruption'){try{$requested=IstNow;$r=Invoke-RestMethod ($engine+'/api/recovery/evaluate/adaptive-product-service?execute=false') -Method Post -TimeoutSec 8;$at=IstNow;$postInterruption=($null-ne $run.timestamps.T1);$postReplacement=($phase -eq 'post-replacement');$run.engineEvaluations+=[ordered]@{timestamp=$at;requestedAt=$requested;execute=$false;phase=$phase;postInterruption=$postInterruption;postReplacement=$postReplacement;decision=$r.decision;reason=$r.reason;actionVerified=$r.actionVerified;response=$r};if($postReplacement){$run.timestamps.T3=$at;$run.timestampEvidence.T3="Post-replacement non-mutating Engine response; replacement UID $($run.replacement.uid), Ready=$($run.replacement.ready).";$run.engineObservation=[ordered]@{decision=$r.decision;reason=$r.reason;verified=($r.kubernetesHealthy -eq $true -or $r.signals.kubernetesHealthy -eq $true);uid=$run.replacement.uid;ready=$run.replacement.ready}}else{$run.timestampEvidence.T3='Unavailable: no post-replacement Engine observation.'};Save-Run;return $r}catch{$run.engineEvaluations+=[ordered]@{timestamp=IstNow;execute=$false;phase=$phase;postInterruption=($null-ne $run.timestamps.T1);postReplacement=($phase -eq 'post-replacement');error=$_.Exception.Message};Save-Run;return $null}}
function Publish-E6([double]$ready,[double]$replacement,[double]$active){try{Invoke-RestMethod ($engine+'/api/recovery/e6/sample') -Method Post -ContentType 'application/json' -Body (@{productReady=$ready;replacementVerified=$replacement;podKillActive=$active}|ConvertTo-Json) -TimeoutSec 5|Out-Null}catch{}}
function Reset-E6Events{Invoke-RestMethod ($engine+'/api/recovery/e6/events/start') -Method Post -Headers @{'X-E6-Runner'='local-fixed-e6'} -ContentType 'application/json' -Body (@{runId=$runId}|ConvertTo-Json -Compress) -TimeoutSec 5|Out-Null;return [DateTimeOffset]::Now}
function Publish-E6Event([hashtable]$evidence){try{$evidence.runId=$runId;Invoke-RestMethod ($engine+'/api/recovery/e6/events/observe') -Method Post -Headers @{'X-E6-Runner'='local-fixed-e6'} -ContentType 'application/json' -Body ($evidence|ConvertTo-Json -Compress) -TimeoutSec 5|Out-Null;return $true}catch{$run.telemetry.error=$_.Exception.Message;return $false}}
function Wait-E6EventScrape([int]$interruption,[int]$replacement,[DateTimeOffset]$publishedAt){
  $a='adaptive_recovery_e6_interruption_observed{job="adaptive-recovery-engine-e2"}'
  $b='adaptive_recovery_e6_healthy_replacement_verified{job="adaptive-recovery-engine-e2"}'
  $url='http://127.0.0.1:19090/api/v1/query?query='
  $deadline=[DateTimeOffset]::UtcNow.AddSeconds(25)
  do{
    try{
      $av=Invoke-RestMethod ($url+[uri]::EscapeDataString($a)) -TimeoutSec 3
      $at=Invoke-RestMethod ($url+[uri]::EscapeDataString('timestamp('+$a+')')) -TimeoutSec 3
      $bv=Invoke-RestMethod ($url+[uri]::EscapeDataString($b)) -TimeoutSec 3
      $bt=Invoke-RestMethod ($url+[uri]::EscapeDataString('timestamp('+$b+')')) -TimeoutSec 3
      if(Test-E6EventScrape -InterruptionValue $av -InterruptionTimestamp $at -ReplacementValue $bv -ReplacementTimestamp $bt -ExpectedInterruption $interruption -ExpectedReplacement $replacement -PublishedAt $publishedAt){return $true}
    }catch{$run.telemetry.error=$_.Exception.Message}
    if([DateTimeOffset]::UtcNow -lt $deadline){Start-Sleep -Seconds 2}
  }while([DateTimeOffset]::UtcNow -lt $deadline)
  return $false
}
function Duration([string]$a,[string]$b){if($a-and$b){$x=[DateTimeOffset]::Parse($a);$y=[DateTimeOffset]::Parse($b);if($y-ge$x){return ($y-$x).ToString()}};return $null}
try{
  $base=Product-Snapshot;if(-not$base-or-not$base.ready-or-not(Product-Health)){ $run.result='BLOCKED';$run.experimentOutcome='Preflight blocked: Product must be Ready and health UP';Save-Run;exit 1 };$baselineUid=$base.uid;$run.baseline=[ordered]@{pod=$base.name;uid=$base.uid;ready=$base.ready;health=$true};$run.readiness.before=$true;Publish-E6 1 0 0
  $existing=Chaos-Status;if($existing){$run.result='BLOCKED';$run.experimentOutcome='Preflight blocked: E6 PodChaos already exists';Save-Run;exit 1};if(Other-Experiment-Running){$run.result='BLOCKED';$run.experimentOutcome='Preflight blocked: another experiment is running';Save-Run;exit 1};Save-Run
  if($CheckOnly){K @('apply','--dry-run=server','-f',$manifest);$run.result='CHECK_ONLY_PASS';$run.runStatus='Completed';$run.experimentOutcome='Not applicable — no live fault was created';Save-Run;exit 0}
  try{$resetAt=Reset-E6Events}catch{$run.result='BLOCKED';$run.experimentOutcome='Preflight blocked: E6 event reset failed before fault creation: '+$_.Exception.Message;Save-Run;exit 1}
  if(-not(Wait-E6EventScrape 0 0 $resetAt)){$run.result='BLOCKED';$run.experimentOutcome='Preflight blocked: Prometheus did not scrape fresh zero E6 event indicators before fault creation';Save-Run;exit 1};$run.telemetry.resetScraped=$true;Save-Run
  K @('apply','-f',$manifest);$created=$true;$run.chaos.created=$true;$c=KJson @('-n',$Namespace,'get','podchaos',$ChaosName,'-o','json');$uid=$c.metadata.uid;$run.chaos.uid=$uid;Save-Run
  if(Wait-Injected){$run.timestamps.T0=IstNow;$run.timestampEvidence.T0='PodChaos status condition AllInjected=True/Injected=True observed.'}else{$run.result='FAILED';$run.experimentOutcome='Injection not verified'};Save-Run
  for($i=0;$i-lt 20;$i++){ $s=Product-Snapshot;$h=Product-Health;$sampleAt=IstNow;$run.measurements+=[ordered]@{at=$sampleAt;phase='interruption';pod=if($s){$s.name}else{$null};uid=if($s){$s.uid}else{$null};ready=if($s){$s.ready}else{$false};health=$h};if(-not$s-or-not$s.ready-or-not$h){$run.timestamps.T1=$sampleAt;$run.timestampEvidence.T1='Product interruption observed by pod readiness/health check.';$run.readiness.interrupted=$true;$run.telemetry.interruptionPublished=Publish-E6Event @{event='product-interruption-observed';ready=[bool]($s-and$s.ready);health=[bool]$h};Publish-E6 0 0 1;Save-Run;break};Start-Sleep 1 };$null=Evaluate 'interruption'
  for($i=0;$i-lt 40;$i++){ $s=Product-Snapshot;if($s-and$s.ready-and$s.uid-ne$baselineUid){$forwardOk=Ensure-ProductForward;$replacementHealth=($forwardOk-and(Product-Health));$run.replacement=[ordered]@{pod=$s.name;uid=$s.uid;ready=$s.ready;health=$replacementHealth};$run.timestamps.T2=IstNow;$run.timestampEvidence.T2='Ready Product pod with UID different from baseline detected.';Publish-E6 1 1 0;$null=Evaluate 'post-replacement';if($run.replacement.health){$run.timestamps.T4=IstNow;$run.timestampEvidence.T4='Replacement Product pod Ready and Product health returned UP after ensuring the Product forward.';$run.telemetry.healthyReplacementPublished=Publish-E6Event @{event='healthy-replacement-verified';baselineUid=$baselineUid;replacementUid=$run.replacement.uid;ready=$true;health=$true};Save-Run};break};Start-Sleep 1 }
  $run.result=if($run.timestamps.T3 -and $run.timestamps.T4){'PASSED'}else{'INCOMPLETE'};$run.experimentOutcome=if($run.result -eq 'PASSED'){'KUBERNETES_SELF_HEALING_OBSERVED'}else{'Replacement/readiness/Engine observation evidence incomplete'};Save-Run
}catch{$run.result='FAILED';$run.experimentOutcome=$_.Exception.Message;Save-Run;throw}
finally{if($CheckOnly){$run.cleanup.attempted=$false;$run.cleanup.status='Not applicable — no live fault was created';$run.runStatus='Completed';Save-Run;Write-Output "RUN_RECORD=$path"}else{$run.cleanup.attempted=$true;try{if($created){$live=try{KJson @('-n',$Namespace,'get','podchaos',$ChaosName,'-o','json')}catch{$null};if($live-and$live.metadata.uid-eq$uid){K @('delete','podchaos',$ChaosName,'-n',$Namespace,'--wait=true');$run.chaos.deleted=$true}};$gone=$false;for($i=0;$i-lt 15;$i++){if(Chaos-Absent){$gone=$true;break};Start-Sleep 1};$run.chaos.absenceVerified=$gone;$final=Product-Snapshot;$healthy=($final-and$final.ready-and(Ensure-ProductForward)-and(Product-Health));$run.readiness.after=$healthy;$replacementVerified=[int]($run.replacement.uid-and$run.replacement.uid-ne$baselineUid-and$run.replacement.ready);Publish-E6 ([int]$healthy) $replacementVerified 0;$run.cleanup.status=if($run.chaos.absenceVerified-and$healthy){'Passed'}else{'Failed'};$run.timestamps.T5=if($run.cleanup.status-eq'Passed'){IstNow}else{$null};if($run.timestamps.T5){$run.timestampEvidence.T5='E6 PodChaos absence and Product Ready/health independently verified.'};$run.timestamps.recoveryTime=Duration $run.timestamps.T1 $run.timestamps.T4;$run.timestamps.faultToRecoveryTime=Duration $run.timestamps.T0 $run.timestamps.T4;$run.timestamps.cleanupCompletionTime=Duration $run.timestamps.T0 $run.timestamps.T5;if($run.cleanup.status-ne'Passed' -and $run.result -eq 'PASSED'){$run.result='FAILED'}}catch{$run.cleanup.status='Failed';$run.cleanup.error=$_.Exception.Message;$run.result='FAILED'};$run.runStatus=if($run.cleanup.status-eq'Passed'){'Completed'}else{'Failed'};Save-Run;if($run.telemetry.resetScraped){$afterCleanup=[DateTimeOffset]::Now;$run.telemetry.eventsScraped=Wait-E6EventScrape ([int]([bool]$run.timestamps.T1)) ([int]([bool]$run.timestamps.T4)) $afterCleanup;if(-not$run.telemetry.eventsScraped -and -not$run.telemetry.error){$run.telemetry.error='No fresh Prometheus scrape of the observed E6 event values within 25 seconds.'};Save-Run};Write-Output "RUN_RECORD=$path"}}
